import os
import torch


class Config:
    """
    Centralized configuration for the Deep Averaging Network (DAN) Regressor pipeline.
    """

    # =========================================
    # Random Seed for Reproducibility
    # =========================================
    SEED = 42

    # =========================================
    # File Paths and Directories
    # =========================================
    # Input Metadata Paths (Generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    # Using 'idea_1' as the specific working directory for this approach
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Specific Output File Paths
    # Path to save the trained model weights
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "dan_model.pth")
    # Path to save the final submission file
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    # Path for caching processed datasets (e.g., vocab, tokenized data)
    CACHE_DIR = WORKING_DIR

    # =========================================
    # Data Processing Hyperparameters
    # =========================================
    # Maximum size of the vocabulary. Top N most frequent words are kept.
    VOCAB_SIZE = 20000

    # Maximum sequence length. Essays longer than this will be truncated, shorter will be padded.
    # Mean word count is ~368, max is ~1300. 800 covers the vast majority of content.
    MAX_LEN = 800

    # Regex pattern for tokenization (alphanumeric words)
    TOKEN_PATTERN = r"(?u)\b\w+\b"

    # Special tokens
    UNK_TOKEN = "<UNK>"
    PAD_TOKEN = "<PAD>"

    # =========================================
    # Model Architecture Hyperparameters
    # =========================================
    # Dimension of the dense word embeddings
    EMBED_DIM = 128

    # Dimension of the hidden layer in the LSTM and MLP regressor
    HIDDEN_DIM = 128

    # Dropout probability for regularization
    DROPOUT_PROB = 0.3

    # Output dimension (1 for regression)
    OUTPUT_DIM = 1

    # =========================================
    # Training Hyperparameters
    # =========================================
    # Batch size for training and validation
    BATCH_SIZE = 64

    # Learning rate for the optimizer
    LEARNING_RATE = 0.001

    # Maximum number of training epochs
    NUM_EPOCHS = 30

    # Early stopping patience (number of epochs with no improvement)
    PATIENCE = 5

    # =========================================
    # Compute Settings
    # =========================================
    # Device selection (GPU if available)
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Number of workers for DataLoader
    NUM_WORKERS = 2

    # =========================================
    # Setup
    # =========================================
    @classmethod
    def setup_directories(cls):
        """Creates necessary directories if they don't exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Execute setup immediately when module is imported
Config.setup_directories()
